function generate_digest(val: uint64, reg_type: enum { INT, FP16, FP32, FP64, FLAG }): uint12
  if reg_type == INT then
    // Count identical leading/trailing bits matching MSB/LSB or zeros, saturated at 63 (6 bits)
    trailing_count = min(count_trailing_zeros_or_ones(val), 63)
    leading_count  = min(count_leading_zeros_or_ones(val), 63)
    lsb6           = val & 0x3F
    // XOR-folded overlapping layout as in Figure 6(a)
    digest = (trailing_count & 0x3F) ^ ((leading_count & 0x3F) << 3) ^ ((lsb6 & 0x3F) << 6)
    return digest & 0xFFF
  else if reg_type == FP16 then
    // Val[15:13]: sign bit and 2 exponent bits placed at digest[5:3]
    return ((val >> 13) & 0x7) << 3
  else if reg_type == FP32 then
    // Val[31:26]: sign bit and 5 exponent bits placed at digest[8:3]
    return ((val >> 26) & 0x3F) << 3
  else if reg_type == FP64 then
    // Val[63:55]: sign bit and 8 exponent bits placed at digest[11:3]
    return ((val >> 55) & 0x1FF) << 3
  else if reg_type == FLAG then
    // 4-bit flag replicated three times
    flag4 = val & 0xF
    return flag4 | (flag4 << 4) | (flag4 << 8)
  end if

function on_pipeline_squash(mispredicted_rob_tag: uint14):
  for r = 0 to 64 do
    // If register was waiting on an instruction flushed on the wrong path, clear it
    if reg_status_table[r].valid == 0 then
      if is_tag_squashed(reg_status_table[r].payload, mispredicted_rob_tag) then
        // Invalidate or clear to avoid hanging
        reg_status_table[r].payload = 0
      end if
    end if
    // Any instruction that completed execution prior to flush remains valid!
  end for
